<template><view class="overview"><view v-if="busy" class="state">正在核验组织与权限…</view><view v-if="error" class="state error">{{error}}</view><template v-if="ready"><view class="scope"><text>{{organizationName||'尚未选择组织'}}</text><button @tap="switchOrganization">切换组织 ›</button></view><view class="group"><button v-for="item in entries" :key="item.url" class="row" @tap="open(item.url)"><text>{{item.title}}</text><text>›</text></button></view><OrganizationOwnerTransfer v-if="organizationId" :identity="identity" :organization-id="organizationId"/></template></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import {request} from '@/api/http';import {getMiniappCapabilities} from '@/api/capability';import {onboardingApi} from '@/api/organization-onboarding';import {getParentSession} from '@/session/parent-session';import {getOrganizationSession} from '@/session/organization-session';import {isParentIdentity} from '@/models/parent-identity';import OrganizationOwnerTransfer from '@/components/OrganizationOwnerTransfer.vue';
const identity=ref<'parent'|'organization'>('parent'),entries=ref<{title:string;url:string}[]>([]),organizationName=ref(''),organizationId=ref(''),busy=ref(false),ready=ref(false),error=ref('');let epoch=0,verifiedToken='';const session=()=>identity.value==='parent'?getParentSession():getOrganizationSession();
onLoad(q=>{identity.value=q?.identity==='organization'?'organization':'parent';});function clear(){epoch++;entries.value=[];organizationName.value='';organizationId.value='';ready.value=false;busy.value=false;verifiedToken='';}onHide(clear);onUnload(clear);
onShow(async()=>{clear();const n=epoch,t=session()?.accessToken;busy.value=true;error.value='';try{if(!t)throw Error('请先登录');const [me,c]=await Promise.all([request<{parentProfile?:boolean;userType:string;clientType:string;roleCodes:string[];permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${t}`}}),getMiniappCapabilities()]);if(n!==epoch||session()?.accessToken!==t)return;const parent=identity.value==='parent';if(parent&&!isParentIdentity(me))throw Error('当前会话不是成长伙伴');if(!me.permissionCodes.includes('ORGANIZATION_ONBOARDING_READ'))throw Error('没有我的组织页面权限');const organizations=await onboardingApi.organizations(t);if(n!==epoch||session()?.accessToken!==t)return;const orgs=organizations.filter(o=>parent?o.typeCode==='FAMILY'&&o.canEnterFamily:o.canEnterInstitution);const chosen=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};if(chosen?.accessToken===t&&chosen.organizationId){const org=orgs.find(o=>o.id===chosen.organizationId);if(!org)throw Error('当前组织不可访问，请重新选择');organizationName.value=org.name;organizationId.value=org.id;}
const has=(code:string)=>me.permissionCodes.includes(code),add=(ok:boolean,title:string,url:string)=>{if(ok)entries.value.push({title,url});};const suffix='?identity='+identity.value;
add(parent&&['STUDENT_READ','STUDENT_CREATE'].some(has),'我的孩子','/pages/parent-children/parent-children');add(has('ORG_MEMBER_READ'),'组织成员','/pages/organization-members/organization-members'+suffix);add(parent?has('STUDENT_ENROLLMENT_REQUEST_CREATE'):['STUDENT_ENROLLMENT_INVITE_CREATE','STUDENT_ENROLLMENT_REVIEW'].some(has),parent?'关联学校或培训机构':'班级入学','/pages/institution-enrollment/institution-enrollment'+suffix);add(parent&&c.parentRelationshipManagementEnabled,'陪伴关系与扫一扫','/pages/parent-relationships/parent-relationships');add(c.attendanceManagementEnabled===true&&!me.roleCodes.includes('SYS_AUDITOR')&&has('ATTENDANCE_READ'),'考勤记录','/pages/attendance/attendance'+suffix);add(parent&&c.anonymousClassRankEnabled===true&&has('MINIAPP_ANONYMOUS_CLASS_RANK_READ'),'班级匿名排行','/pages/anonymous-ranks/anonymous-ranks');add(parent,'排行查看授权','/pages/anonymous-ranks/anonymous-ranks?withdraw=true');add(!parent&&has('CLASS_READ'),'机构层级管理','/pages/organization-hierarchy/organization-hierarchy');add(parent&&c.parentAccountLifecycleEnabled,'联系方式与账号','/pages/parent-account-lifecycle/parent-account-lifecycle');add(parent&&c.studentWechatAuthEnabled===true,'孩子微信绑定','/pages/parent-student-wechat/parent-student-wechat');add(!parent&&c.studentOrganizationRelationshipEnabled,'学员关系','/pages/organization-students/organization-students');add(!parent&&c.studentExceptionReportEnabled===true&&has('EXCEPTION_REPORT_READ'),'异常报备','/pages/exception-reports/exception-reports'+suffix);add(!parent&&c.parentMobileManualRecoveryEnabled===true,'家长手机人工恢复','/pages/organization-parent-mobile-recovery/organization-parent-mobile-recovery');add(!parent&&c.studentAccountCancellationEnabled===true,'学员账号注销','/pages/organization-student-cancellation/organization-student-cancellation');add(!parent,'账号设置','/pages/account-settings/account-settings'+suffix);verifiedToken=t;ready.value=true;
}catch(e){if(n===epoch)error.value=e instanceof Error?e.message:'组织加载失败';}finally{if(n===epoch)busy.value=false;}});
function open(url:string){if(ready.value&&session()?.accessToken===verifiedToken)uni.navigateTo({url});}function switchOrganization(){open('/pages/my-organizations/my-organizations?identity='+identity.value+'&choose=1');}
</script>
<style scoped>.overview{padding:32rpx;background:#f5f8f4;min-height:calc(100vh - var(--window-top,0px));box-sizing:border-box;color:#193e32}.title{display:block;font-size:36rpx;font-weight:700;margin-bottom:28rpx}.scope{display:flex;align-items:center;justify-content:space-between;padding:24rpx;border-radius:20rpx;background:#e8f1e5;margin-bottom:24rpx}.group{background:white;border-radius:24rpx;overflow:hidden}.row{display:flex;justify-content:space-between;width:100%;padding:28rpx;background:white;font-size:28rpx;color:#193e32;line-height:1.5;border-bottom:1rpx solid #edf2e9;border-radius:0}.row::after{border:0}.state{padding:24rpx;font-size:26rpx;color:#7c867d}.error{color:#aa5043}button{font-size:25rpx;color:#1d6044;background:#edf5e8}</style>
